import{_ as e,o as a,c as i,an as o}from"./chunks/framework.UzZ94frR.js";const p=JSON.parse('{"title":"Estimators","description":"","frontmatter":{},"headers":[],"relativePath":"estimators.md","filePath":"estimators.md","lastUpdated":null}'),d={name:"estimators.md"};function r(s,t,c,n,l,h){return a(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="Estimators" tabindex="-1">Estimators <a class="header-anchor" href="#Estimators" aria-label="Permalink to &quot;Estimators {#Estimators}&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:right;">Method</th><th style="text-align:right;">Population parameters</th><th style="text-align:right;">Subject effects</th><th style="text-align:right;">Main output</th></tr></thead><tbody><tr><td style="text-align:right;"><code>empirical_bayes</code> / <code>posthoc</code></td><td style="text-align:right;">Fixed input θ, σ, Ω</td><td style="text-align:right;">Conditional posterior modes (EBEs)</td><td style="text-align:right;"><code>EBEResult.modes</code></td></tr><tr><td style="text-align:right;"><code>focei</code> with <code>interaction = false</code></td><td style="text-align:right;">Fitted by a derivative-free outer search</td><td style="text-align:right;">EBEs at the fit</td><td style="text-align:right;"><code>FOCEResult.theta</code>, <code>.sigma</code>, <code>.omega_matrix</code>, <code>.ofv</code></td></tr><tr><td style="text-align:right;"><code>focei</code> with <code>interaction = true</code> (default)</td><td style="text-align:right;">Fitted by a derivative-free outer search</td><td style="text-align:right;">EBEs at the fit</td><td style="text-align:right;">Same fields, with the variance-Jacobian interaction term</td></tr><tr><td style="text-align:right;"><code>saem</code> with <code>StandardSAEMMH()</code> (default)</td><td style="text-align:right;">Fitted by stochastic approximation</td><td style="text-align:right;">One evolving η chain per subject</td><td style="text-align:right;"><code>SAEMResult.theta</code>, <code>.sigma</code>, <code>.omega_matrix</code>, <code>.acceptance</code></td></tr><tr><td style="text-align:right;"><code>saem</code> with <code>DualAveragingMALA()</code> (experimental)</td><td style="text-align:right;">Fitted by stochastic approximation</td><td style="text-align:right;">Batched proposals with a separate continuously adapted step size per subject</td><td style="text-align:right;"><code>SAEMResult.theta</code>, <code>.sigma</code>, <code>.omega_matrix</code>, <code>.mala_stepsizes</code>, <code>.mala_acceptance</code></td></tr><tr><td style="text-align:right;"><code>saem</code> with <code>WarmupHMCNUTS()</code></td><td style="text-align:right;">Fitted by stochastic approximation</td><td style="text-align:right;">Per-subject WarmupHMC NUTS transitions</td><td style="text-align:right;"><code>SAEMResult.theta</code>, <code>.sigma</code>, <code>.omega_matrix</code>, <code>.nuts_divergences</code></td></tr></tbody></table><p>Empirical Bayes is a conditional calculation at supplied population parameters. FOCE(I) and SAEM estimate population parameters. Their objectives and approximations differ, so compare estimates and predictions on the same data rather than treating objective values as interchangeable. Full joint MCMC can provide a posterior comparison but is not an NLMEEstimation estimator.</p><p>SAEM updates the population parameters every iteration by default. Its Gaussian random-effect mean and covariance use running sufficient statistics. For other coordinates, <code>SAEMOptions(numeric_mstep=:auto)</code> chooses a bounded-memory online optimizer update when all fitted structural <code>θ</code> coordinates have a declared <code>MuReferencing</code> update; otherwise it preserves the historical running-mixture objective. <code>SAEMResult.numeric_mstep</code> reports the selected mode. Explicit <code>:online</code> for undeclared structural <code>θ</code> is a model-specific approximation; the <a href="./saem-benchmarks">BRM benchmark</a> measures that case separately.</p><p>See the <a href="./pk-comparison">PK comparison</a> for one reproducible model, dataset, seeds, and all method calls. The <a href="./saem-benchmarks">SAEM kernel benchmarks</a> compare MH, NUTS, and an experimental batched MALA trial, including their implementation and measurement scripts.</p>',5)])])}const g=e(d,[["render",r]]);export{p as __pageData,g as default};
